cat >> tests/tasks.test.ts <<'EOF'

async function deleteTask(server: Running, id: number | string): Promise<Response> {
  return fetch(`${server.baseUrl}/api/tasks/${id}`, { method: "DELETE" });
}

describe("SL-006 delete a task permanently", () => {
  describe("AC-1: the owner deletes an existing task", () => {
    const dbPath = newDbPath();
    let server: Running | undefined;

    after(async () => {
      await server?.stop();
    });

    it("AC-1: DELETE answers 204, the task leaves the list and stays gone after kill -9 and a restart", async () => {
      server = await startServer(dbPath);
      const { task: doomed } = (await (await createTask(server, "Buy milk")).json()) as {
        task: Task;
      };
      const { task: kept } = (await (await createTask(server, "Walk the dog")).json()) as {
        task: Task;
      };

      const response = await deleteTask(server, doomed.id);
      assert.equal(response.status, 204);
      assert.equal(await response.text(), "");
      assert.deepEqual(
        (await listTasks(server)).map((t) => t.id),
        [kept.id],
      );

      await server.stop();
      server = await startServer(dbPath);
      assert.deepEqual(
        (await listTasks(server)).map((t) => t.id),
        [kept.id],
      );
    });
  });

  describe("AC-2: the task no longer exists", () => {
    let server: Running;

    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-2: deleting an id that never existed answers 404 not_found", async () => {
      const response = await deleteTask(server, 9999);
      assert.equal(response.status, 404);
      const body = (await response.json()) as { error: { code: string; message: string } };
      assert.equal(body.error.code, "not_found");
      assert.equal(typeof body.error.message, "string");
    });

    it("AC-2: deleting the same task twice answers 204 then 404", async () => {
      const { task } = (await (await createTask(server, "Once")).json()) as { task: Task };
      assert.equal((await deleteTask(server, task.id)).status, 204);
      assert.equal((await deleteTask(server, task.id)).status, 404);
    });

    it("AC-2: a non-numeric id answers 404 and deletes nothing", async () => {
      await createTask(server, "Survivor");
      for (const id of ["abc", "1.5", "-1", "1e0"]) {
        assert.equal((await deleteTask(server, id)).status, 404, id);
      }
      assert.ok((await listTasks(server)).some((t) => t.title === "Survivor"));
    });
  });

  describe("AC-1: the page asks for a browser confirmation first", () => {
    let script: string;

    before(async () => {
      const server = await startServer();
      try {
        script = await (await fetch(`${server.baseUrl}/app.js`)).text();
      } finally {
        await server.stop();
      }
    });

    it("AC-1: the script confirms before it sends DELETE and still avoids innerHTML", () => {
      const confirmAt = script.indexOf("confirm(");
      const deleteAt = script.indexOf('"DELETE"');
      assert.ok(confirmAt >= 0 && deleteAt > confirmAt, "confirm() precedes the DELETE request");
      assert.doesNotMatch(script, /innerHTML/);
    });
  });
});
EOF
